import React from 'react';
import { ShieldCheck, Star, Users } from 'lucide-react'; // Modern icons
import { C } from '../data';
import FadeIn from './FadeIn';
import SectionHeader from './SectionHeader';

const cards = [
  { 
    icon: <ShieldCheck size={28} />, 
    title: 'Verified Leads Only', 
    desc: 'Every student request is manually reviewed before being shared with our tutor network.' 
  },
  { 
    icon: <Star size={28} />, 
    title: 'Quality Focused', 
    desc: 'We prioritize long-term student success and sustainable growth over raw lead numbers.' 
  },
  { 
    icon: <Users size={28} />, 
    title: 'Direct Connection', 
    desc: 'We bridge tutors and students directly with zero middleman and 100% transparency.' 
  },
];

export default function About() {
  return (
    <section id="about" style={{ 
      padding: '120px 24px', 
      background: '#000712', // Hero theme matching Deep Blue
      position: 'relative' 
    }}>
      {/* Subtle Background Glow */}
      <div style={{ 
        position: 'absolute', 
        top: '50%', 
        left: '50%', 
        width: '500px', 
        height: '500px', 
        background: 'radial-gradient(circle, rgba(245,166,35,0.03) 0%, transparent 70%)', 
        transform: 'translate(-50%, -50%)',
        zIndex: 0 
      }} />

      <div style={{ maxWidth: 1280, margin: '0 auto', position: 'relative', zIndex: 1 }}>
        {/* Make sure your SectionHeader handles white text for dark theme */}
        <SectionHeader 
          tag="Our Mission" 
          title="Who is TutorBridge?" 
          subtitle="An independent platform dedicated to connecting passionate tutors with students who need them — built on quality, trust, and results." 
        />

        <div style={{ 
          display: 'grid', 
          gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', 
          gap: 32,
          marginTop: 64 
        }}>
          {cards.map((c, i) => (
            <FadeIn key={i} delay={i * 0.15}>
              <div
                style={{ 
                  padding: '48px 32px', 
                  borderRadius: 24, 
                  border: '1px solid rgba(255,255,255,0.08)', 
                  background: 'rgba(255,255,255,0.02)', 
                  backdropFilter: 'blur(10px)',
                  textAlign: 'center', 
                  transition: 'all 0.4s ease', 
                  cursor: 'default',
                  height: '100%'
                }}
                onMouseEnter={e => { 
                  e.currentTarget.style.transform = 'translateY(-10px)'; 
                  e.currentTarget.style.borderColor = C.gold;
                  e.currentTarget.style.background = 'rgba(255,255,255,0.05)';
                  e.currentTarget.style.boxShadow = `0 20px 40px rgba(0,0,0,0.4), 0 0 15px ${C.gold}11`;
                }}
                onMouseLeave={e => { 
                  e.currentTarget.style.transform = 'translateY(0)'; 
                  e.currentTarget.style.borderColor = 'rgba(255,255,255,0.08)';
                  e.currentTarget.style.background = 'rgba(255,255,255,0.02)';
                  e.currentTarget.style.boxShadow = 'none';
                }}
              >
                {/* Icon Container */}
                <div style={{ 
                  width: 64, 
                  height: 64, 
                  borderRadius: 18, 
                  display: 'flex', 
                  alignItems: 'center', 
                  justifyContent: 'center', 
                  margin: '0 auto 24px', 
                  background: `linear-gradient(135deg, ${C.gold}15 0%, ${C.gold}05 100%)`, 
                  color: C.gold,
                  border: `1px solid ${C.gold}33`
                }}>
                  {c.icon}
                </div>

                <h3 style={{ 
                  fontWeight: 700, 
                  fontSize: 19, 
                  marginBottom: 12, 
                  color: '#fff',
                  fontFamily: "'Playfair Display', serif" 
                }}>
                  {c.title}
                </h3>

                <p style={{ 
                  fontSize: 15, 
                  lineHeight: 1.7, 
                  color: 'rgba(255,255,255,0.65)',
                  fontWeight: 400 
                }}>
                  {c.desc}
                </p>
              </div>
            </FadeIn>
          ))}
        </div>
      </div>
    </section>
  );
}
